            if (word1.charAt(i) == word2.charAt(i)) {
                common++;
            }
        }

        // Calculate the sum of the lengths of the two words
        int sum = word1.length() + word2.length();

        // Divide the number of common letters by the sum of the lengths of the two words
        double approximation = (double) common / sum;

        // Return the approximation as a reduced fraction
        return String.format("appx(%s, %s) = %d/%d", word1, word2, common, sum);
    }

