    for (int i = 2; i < cost.length; i++) {
        int tempOne = bestCostOne;
        int tempTwo = bestCostTwo;
        bestCostOne = Math.min(tempOne, tempTwo) + cost[i];
        bestCostTwo = bestCostOne;
        if (tempOne < minCost) {
            minCost = tempOne;
        }
        if (tempTwo < minCost) {
            minCost = tempTwo;
        }
    }
    // Return the minimum cost
    return Math.min(minCost, bestCostTwo);
}

