public static String reverseWords(String s) {
  // split the input string into an array of words using whitespace as the delimiter
  String[] words = s.split("\\s+");

  // create a new string builder to hold the reversed words
  StringBuilder reversedWords = new StringBuilder();

  // iterate over the words
  for (String word : words) {
    // reverse the characters of the current word
    String reversedWord = new StringBuffer(word).reverse().toString();

    // append the reversed word to the string builder
    reversedWords.append(reversedWord);

    // append a space to separate the words
    reversedWords.append(" ");
  }

  // return the reversed words
  return reversedWords.toString();
}

